mapper.sql:
FROM it_service_entitlement

  customer_id = #{customer}
  AND status = 'ACTIVE'
  AND starts_on <= #{today}
  AND ends_on >= #{today}
  AND service_item_id IN (
    SELECT id FROM it_service_item WHERE status = 'ACTIVE'
  )

mapper.select:
